 "config/settings_schema.json": "[\n  {\n    \"name\": \"theme_info\",\n    \"theme_name\": \"AdSpy Storefront\",\n    \"theme_version\": \"1.0.0\",\n    \"theme_author\": \"AdSpy Pro\",\n    \"theme_documentation_url\": \"https://adspy-pro-six.vercel.app/dashboard/launch\",\n    \"theme_support_url\": \"https://adspy-pro-six.vercel.app/dashboard/launch\"\n  },\n  {\n    \"name\": \"Colors\",\n    \"settings\": [\n      { \"type\": \"color\", \"id\": \"color_bg\", \"label\": \"Background\", \"default\": \"#ffffff\" },\n      { \"type\": \"color\", \"id\": \"color_surface\", \"label\": \"Soft background\", \"default\": \"#eef6f3\" },\n      { \"type\": \"color\", \"id\": \"color_text\", \"label\": \"Text\", \"default\": \"#11211b\" },\n      { \"type\": \"color\", \"id\": \"color_accent\", \"label\": \"Buttons and accents\", \"default\": \"#0f766e\" },\n      { \"type\": \"color\", \"id\": \"color_accent_text\", \"label\": \"Text on buttons\", \"default\": \"#ffffff\" },\n      { \"type\": \"color\", \"id\": \"color_sale\", \"label\": \"Sale badges\", \"default\": \"#c2410c\" }\n    ]\n  },\n  {\n    \"name\": \"Typography\",\n    \"settings\": [\n      {\n        \"type\": \"select\",\n        \"id\": \"font_pair\",\n        \"label\": \"Fonts\",\n        \"default\": \"fresh\",\n        \"options\": [\n          { \"value\": \"fresh\", \"label\": \"Plus Jakarta Sans\" },\n          { \"value\": \"bold\", \"label\": \"Archivo Black + Archivo\" },\n          { \"value\": \"luxe\", \"label\": \"Cormorant Garamond + Inter\" },\n          { \"value\": \"playful\", \"label\": \"Fredoka + Nunito\" },\n          { \"value\": \"nordic\", \"label\": \"Fraunces + Inter\" },\n          { \"value\": \"tech\", \"label\": \"Space Grotesk + Inter\" }\n        ]\n      },\n      { \"type\": \"checkbox\", \"id\": \"heading_uppercase\", \"label\": \"Uppercase headings\", \"default\": false }\n    ]\n  },\n  {\n    \"name\": \"Layout\",\n    \"settings\": [\n      { \"type\": \"range\", \"id\": \"page_width\", \"label\": \"Page width\", \"min\": 1000, \"max\": 1600, \"step\": 20, \"unit\": \"px\", \"default\": 1240 },\n      { \"type\": \"range\", \"id\": \"radius\", \"label\": \"Corner roundness\", \"min\": 0, \"max\": 28, \"step\": 1, \"unit\": \"px\", \"default\": 14 },\n      { \"type\": \"checkbox\", \"id\": \"button_pill\", \"label\": \"Pill-shaped buttons\", \"default\": true }\n    ]\n  },\n  {\n    \"name\": \"Store\",\n    \"settings\": [\n      { \"type\": \"text\", \"id\": \"brand_name\", \"label\": \"Store name in the header (empty: the Shopify store name)\" },\n      { \"type\": \"image_picker\", \"id\": \"favicon\", \"label\": \"Favicon\" },\n      { \"type\": \"header\", \"content\": \"Lines under the add-to-cart button\" },\n      { \"type\": \"text\", \"id\": \"trust_line_1\", \"label\": \"Shipping\", \"default\": \"Tracked shipping\" },\n      { \"type\": \"text\", \"id\": \"trust_line_2\", \"label\": \"Returns\", \"default\": \"Easy returns\" },\n      { \"type\": \"text\", \"id\": \"trust_line_3\", \"label\": \"Payment\", \"default\": \"Secure checkout\" }\n    ]\n  },\n  {\n    \"name\": \"Cart\",\n    \"settings\": [\n      { \"type\": \"select\", \"id\": \"cart_type\", \"label\": \"Cart\", \"default\": \"drawer\", \"options\": [{ \"value\": \"drawer\", \"label\": \"Slide-out drawer\" }, { \"value\": \"page\", \"label\": \"Cart page\" }] },\n      { \"type\": \"number\", \"id\": \"free_shipping_threshold\", \"label\": \"Free shipping from (store currency; 0 hides the progress bar)\", \"default\": 0 },\n      { \"type\": \"number\", \"id\": \"delivery_min_days\", \"label\": \"Delivery time from (business days)\", \"default\": 0 },\n      { \"type\": \"number\", \"id\": \"delivery_max_days\", \"label\": \"Delivery time to (business days; 0 hides the delivery estimate)\", \"default\": 0 },\n      { \"type\": \"checkbox\", \"id\": \"show_add_another\", \"label\": \"Offer to add one more of the same product\", \"default\": true },\n      { \"type\": \"checkbox\", \"id\": \"show_payment_icons\", \"label\": \"Show payment icons under the checkout button\", \"default\": true },\n      { \"type\": \"number\", \"id\": \"guarantee_days\", \"label\": \"Money-back guarantee on product pages (days; 0 hides it)\", \"default\": 0 }\n    ]\n  },\n  {\n    \"name\": \"Social media\",\n    \"settings\": [\n      { \"type\": \"url\", \"id\": \"social_instagram\", \"label\": \"Instagram\" },\n      { \"type\": \"url\", \"id\": \"social_tiktok\", \"label\": \"TikTok\" },\n      { \"type\": \"url\", \"id\": \"social_facebook\", \"label\": \"Facebook\" }\n    ]\n  }\n]\n",
 "layout/password.liquid": "<!doctype html>\n<html lang=\"{{ request.locale.iso_code }}\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n    <title>{{ shop.name }}</title>\n    {% render 'theme-style' %}\n    {{ 'base.css' | asset_url | stylesheet_tag }}\n    {{ content_for_header }}\n  </head>\n  <body class=\"template-password\">\n    <main id=\"MainContent\" class=\"content\" role=\"main\">\n      {{ content_for_layout }}\n    </main>\n  </body>\n</html>\n",
 "layout/theme.liquid": "<!doctype html>\n<html lang=\"{{ request.locale.iso_code }}\" class=\"no-js\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n    <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n    <meta name=\"theme-color\" content=\"{{ settings.color_bg }}\">\n    <link rel=\"canonical\" href=\"{{ canonical_url }}\">\n    {%- if settings.favicon != blank -%}\n      <link rel=\"icon\" type=\"image/png\" href=\"{{ settings.favicon | image_url: width: 64, height: 64 }}\">\n    {%- endif -%}\n    <title>\n      {{ page_title }}\n      {%- if current_tags %} &ndash; {{ current_tags | join: ', ' }}{% endif -%}\n      {%- if current_page != 1 %} &ndash; {{ 'general.page' | t: page: current_page }}{% endif -%}\n      {%- unless page_title contains shop.name %} &ndash; {{ shop.name }}{% endunless -%}\n    </title>\n    {%- if page_description -%}\n      <meta name=\"description\" content=\"{{ page_description | escape }}\">\n    {%- endif -%}\n    {% render 'meta-tags' %}\n    {% render 'theme-style' %}\n    {{ 'base.css' | asset_url | stylesheet_tag }}\n    <script src=\"{{ 'theme.js' | asset_url }}\" defer=\"defer\"></script>\n    <script>document.documentElement.className = document.documentElement.className.replace('no-js', 'js');</script>\n    {{ content_for_header }}\n  </head>\n  <body class=\"template-{{ template.name }}\">\n    <a class=\"skip-link\" href=\"#MainContent\">{{ 'accessibility.skip_to_content' | t }}</a>\n    {% sections 'header-group' %}\n    <main id=\"MainContent\" class=\"content\" role=\"main\" tabindex=\"-1\">\n      {{ content_for_layout }}\n    </main>\n    {% sections 'footer-group' %}\n    {%- if settings.cart_type == 'drawer' -%}{% section 'cart-drawer' %}{%- endif -%}\n    <script>\n      window.theme = {\n        routes: { cart: {{ routes.cart_url | json }}, cartAdd: {{ routes.cart_add_url | json }}, cartChange: {{ routes.cart_change_url | json }}, root: {{ routes.root_url | json }} },\n        strings: { added: {{ 'products.added' | t | json }}, soldOut: {{ 'products.sold_out' | t | json }}, addToCart: {{ 'products.add_to_cart' | t | json }}, unavailable: {{ 'products.unavailable' | t | json }}, error: {{ 'general.error' | t | json }} },\n        cartType: {{ settings.cart_type | json }},\n        moneyFormat: {{ shop.money_format | json }}\n      };\n    </script>\n  </body>\n</html>\n",
