 "templates/gift_card.liquid": "{%- layout none -%}\n<!doctype html>\n<html lang=\"{{ request.locale.iso_code }}\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n    <title>{{ 'gift_card.title' | t }} &ndash; {{ shop.name }}</title>\n    {% render 'theme-style' %}\n    {{ 'base.css' | asset_url | stylesheet_tag }}\n    {{ content_for_header }}\n  </head>\n  <body>\n    <main class=\"section\">\n      <div class=\"page-width page-width--xs center stack\">\n        <p class=\"logo__text\">{{ settings.brand_name | default: shop.name | escape }}</p>\n        <h1 class=\"h2\">{{ 'gift_card.title' | t }}</h1>\n        <p class=\"h1\">{{ gift_card.balance | money }}</p>\n        {%- if gift_card.expired -%}<p class=\"note\">{{ 'gift_card.expired' | t }}</p>{%- endif -%}\n        <p class=\"small muted\">{{ 'gift_card.code' | t }}</p>\n        <p class=\"gift-code\">{{ gift_card.code | format_code }}</p>\n        <a href=\"{{ shop.url }}\" class=\"btn\">{{ 'gift_card.shop' | t }}</a>\n      </div>\n    </main>\n  </body>\n</html>\n",
 "templates/index.json": "{\n  \"sections\": {\n    \"hero\": {\n      \"type\": \"hero\",\n      \"settings\": {\n        \"heading\": \"Made for everyday life\",\n        \"text\": \"Thoughtful products, shipped to your door.\",\n        \"button_label\": \"Shop now\"\n      }\n    },\n    \"trust\": {\n      \"type\": \"trust-bar\",\n      \"blocks\": {\n        \"t1\": {\n          \"type\": \"item\",\n          \"settings\": {\n            \"icon\": \"truck\",\n            \"text\": \"Tracked shipping\"\n          }\n        },\n        \"t2\": {\n          \"type\": \"item\",\n          \"settings\": {\n            \"icon\": \"lock\",\n            \"text\": \"Secure checkout\"\n          }\n        },\n        \"t3\": {\n          \"type\": \"item\",\n          \"settings\": {\n            \"icon\": \"chat\",\n            \"text\": \"Friendly support\"\n          }\n        }\n      },\n      \"block_order\": [\n        \"t1\",\n        \"t2\",\n        \"t3\"\n      ],\n      \"settings\": {}\n    },\n    \"products\": {\n      \"type\": \"featured-collection\",\n      \"settings\": {\n        \"heading\": \"Shop the collection\"\n      }\n    },\n    \"news\": {\n      \"type\": \"newsletter\",\n      \"settings\": {}\n    }\n  },\n  \"order\": [\n    \"hero\",\n    \"trust\",\n    \"products\",\n    \"news\"\n  ]\n}\n",
